import{_ as o,l,o as e,c as s,v as i,p as n,x as t,d as p,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"QUIC 连接迁移","description":"","frontmatter":{"title":"QUIC 连接迁移","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/quic-migration.md","filePath":"cs/quic-migration.md","lastUpdated":1789023840000}'),C={name:"cs/quic-migration.md"};function E(h,a,_,m,u,A){const r=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=i('<h1 id="quic-连接迁移" tabindex="-1">QUIC 连接迁移 <a class="header-anchor" href="#quic-连接迁移" aria-label="Permalink to &quot;QUIC 连接迁移&quot;">​</a></h1><div class="epigraph"><p>连接 ID 与地址解耦：路径变了用 PATH_CHALLENGE 验证新路，字节流不断；NAT 重绑与 Wi‑Fi/蜂窝切换是同一机制。</p><footer>—— 据 RFC 9000 连接迁移；RFC 9002 恢复对照整理</footer></div><p><a href="/cs/quic-streams-0rtt">上一课</a> 的连接还钉在四元组上叙事。TCP 换 IP 必断。<a href="/cs/mptcp">MPTCP</a> 用子流。缺口是 <strong>QUIC 迁移</strong>：CID、路径验证、连接 ID 隐私。本课不把 BBRv2 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>手机从 Wi‑Fi 到 LTE，TCP 四元组变，状态机作废。QUIC：包头 CID 让服务器认出连接，再验证新路径防劫持。旧路径可并存短暂。与蜂窝核心锚点对照：那是网络侧保 IP；迁移是端侧换 IP 仍保运输。Anonymizing CID 轮换防链路追踪。</p><p>不要把迁移写成 0-RTT 的一部分：0-RTT 是早数据，迁移是路径。</p><p><span class="marginnote">RFC 9000 第 9 节。禁用迁移的中间盒存在。本课不写负载均衡怎么粘 CID，后课 Maglev 会沾边。</span></p><h3 id="cid-解耦地址" tabindex="-1">CID 解耦地址 <a class="header-anchor" href="#cid-解耦地址" aria-label="Permalink to &quot;CID 解耦地址&quot;">​</a></h3><p>新路径要挑战验证。拥塞状态不可盲目继承。服务器须能按 CID 路由到同一实例。与 0-RTT 不是一件事。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：旧路径 → 新地址 → PATH_CHALLENGE/RESPONSE → 切主路径。对照 MPTCP ADD_ADDR。卫星切换网关类似。</p>',11)),(e(),n(d,null,{default:t(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CID%5B%22%E8%BF%9E%E6%8E%A5%20ID%22%5D%20--%3E%20REC%5B%22%E5%AF%B9%E7%AB%AF%E8%AE%A4%E5%87%BA%22%5D%0A%20%20NEW%5B%22%E6%96%B0%E5%9B%9B%E5%85%83%E7%BB%84%22%5D%20--%3E%20CH%5B%22%E8%B7%AF%E5%BE%84%E9%AA%8C%E8%AF%81%22%5D%0A%20%20CH%20--%3E%20SW%5B%22%E5%88%87%E6%8D%A2%E5%8F%91%E9%80%81%E8%B7%AF%E5%BE%84%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>拥塞状态是否继承是实现：新路径 BDP 不同，盲目继承会炸。保活用 PING 帧，短于 TCP keepalive。SYN cookies 无对应，Retry 与 CID 由服务器发。ECMP 哈希因四元组变而换路，本就可能，迁移只是显式。</p><p>安全：未验证的新路径不能立刻收非探测数据，防迁移劫持。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 QUIC 多路径扩展的全部。BBRv2/v3 是下一课。后课默认：CID 使运输跨地址存活；要验证路径。</p><p>服务器集群必须能按 CID 路由到同一实例，否则迁移失败。</p><p>上一课留下的缺口在本课收口；「QUIC 连接迁移」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/bbr-v2-v3">BBRv2 / v3</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CID 解耦连接与地址。</li><li>新路径要挑战验证。</li><li>拥塞状态不可盲目带着走。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9000。</li></ul>',10))])}const T=o(C,[["render",E]]);export{D as __pageData,T as default};
